        }
    }
    if let Some(l) = tokens.last() {
        if is_redir(l.ty) {
            return ERR_REDIR_EOF;
        }
        if l.ty == TokenType::Pipe {
            return ERR_PIPE_EOF;
        }
    }
    SYNTAX_OK
}

