                let ch = b[i];
                if ch == b'"' || ch == b'\'' {
                    if ch == b'\'' {
                        quoted = 1;
                    }
                    word.push(if ch == b'\'' { 1 } else { 2 });
                    i += 1;
                    while i < b.len() && b[i] != ch {
                        word.push(b[i]);
                        i += 1;
                    }
                    if i >= b.len() {
                        return None;
                    }
                    word.push(3);
                    i += 1;
                } else {
                    word.push(ch);
                    i += 1;
                }
            }
            if !word.is_empty() {
                tokens.push(Token { ty: TokenType::Word, value: to_string(word), quoted });
            }
        }
    }
    if tokens.is_empty() {
        None
    } else {
        Some(tokens)
    }
}

fn is_invalid_char(input: &str) -> bool {
    let mut in_quote = false;
    let mut quote_char = 0u8;
    for &c in input.as_bytes() {
        if (c == b'"' || c == b'\'') && !in_quote {
            in_quote = true;
            quote_char = c;
        } else if c == quote_char && in_quote {
            in_quote = false;
            quote_char = 0;
        } else if !in_quote && (c == b';' || c == b'\\') {
            return true;
        }
    }
    false
}

fn is_unclosed_quotes(input: &str) -> bool {
    let mut quote = 0u8;
    for &c in input.as_bytes() {
        if (c == b'"' || c == b'\'') && quote == 0 {
            quote = c;
        } else if c == quote {
            quote = 0;
        }
    }
    quote != 0
}

fn is_redir(t: TokenType) -> bool {
    matches!(
